function drawTogepiSpottedEgg(ctx, cx, cy, scale, t, blink = false) {
  ctx.save();
  ctx.translate(cx, cy);
  ctx.scale(scale, scale);

  const breathPhase = t * 2.3;
  const breathSin = Math.sin(breathPhase);
  const sY = 1.0 + 0.05 * breathSin;
  const sX = 1.0 - 0.025 * breathSin;
  const by = -Math.abs(breathSin) * 3.0;

  // Bóng sàn
  ctx.fillStyle = '#1e293b';
  ctx.beginPath(); ctx.ellipse(0, 42, 26 * (1.0 - 0.15 * breathSin), 6, 0, 0, Math.PI * 2); ctx.fill();

  // Chân
  ctx.fillStyle = '#fef08a';
  ctx.beginPath(); ctx.roundRect(-16, by + 30, 10, 8, 3); ctx.fill();
  ctx.beginPath(); ctx.roundRect(6,   by + 30, 10, 8, 3); ctx.fill();

  // Đầu vàng & 5 gai
  ctx.beginPath(); ctx.ellipse(0, by - 12, 18 * sX, 16 * sY, 0, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.moveTo(-20, by - 14); ctx.lineTo(-26, by - 32); ctx.lineTo(-12, by - 18); ctx.fill();
  ctx.beginPath(); ctx.moveTo(-14, by - 18); ctx.lineTo(-10, by - 38); ctx.lineTo(-2,  by - 20); ctx.fill();
  ctx.beginPath(); ctx.moveTo(-4,  by - 20); ctx.lineTo(0,   by - 40); ctx.lineTo(4,   by - 20); ctx.fill();
  ctx.beginPath(); ctx.moveTo(2,   by - 20); ctx.lineTo(10,  by - 38); ctx.lineTo(14,  by - 18); ctx.fill();
  ctx.beginPath(); ctx.moveTo(12,  by - 18); ctx.lineTo(26,  by - 32); ctx.lineTo(20,  by - 14); ctx.fill();

  // Vỏ trứng trắng
  ctx.fillStyle = '#ffffff';
  ctx.beginPath(); ctx.ellipse(0, by + 10, 22 * sX, 20 * sY, 0, 0, Math.PI * 2); ctx.fill();
  // Răng cưa vỏ trứng
  ctx.beginPath();
  ctx.moveTo(-18, by - 2); ctx.lineTo(-12, by - 8); ctx.lineTo(-6, by - 2);
  ctx.lineTo(0, by - 8); ctx.lineTo(6, by - 2);
  ctx.lineTo(12, by - 8); ctx.lineTo(18, by - 2);
  ctx.fill();

  // Đốm vỏ trứng
  ctx.fillStyle = '#38bdf8';
  ctx.beginPath(); ctx.moveTo(-8, by + 8); ctx.lineTo(2, by + 2); ctx.lineTo(-2, by + 18); ctx.fill();
  ctx.beginPath(); ctx.moveTo(4, by + 18); ctx.lineTo(14, by + 14); ctx.lineTo(10, by + 24); ctx.fill();
  ctx.fillStyle = '#ef4444';
  ctx.fillRect(8, by + 4, 8, 8);
  ctx.beginPath(); ctx.moveTo(-16, by + 6); ctx.lineTo(-12, by + 2); ctx.lineTo(-10, by + 12); ctx.fill();

  // Mắt
  if (!blink) {
    ctx.fillStyle = '#0f172a';
    ctx.beginPath(); ctx.ellipse(-8, by - 16, 3, 6, 0, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.ellipse(8,  by - 16, 3, 6, 0, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#ffffff';
    ctx.beginPath(); ctx.arc(-9, by - 18, 1, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(7,  by - 18, 1, 0, Math.PI * 2); ctx.fill();
  }

  // Miệng
  ctx.fillStyle = '#881337';
  ctx.beginPath(); ctx.moveTo(0, by - 8); ctx.lineTo(-4, by - 12); ctx.lineTo(4, by - 12); ctx.fill();

  // Tay
  ctx.fillStyle = '#fef08a';
  ctx.beginPath(); ctx.arc(-20, by - 2, 4, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(20,  by - 2, 4, 0, Math.PI * 2); ctx.fill();

  ctx.restore();
}
